const cfg = $input.first().json;
const emailConfigured = !!(cfg.developer_email && cfg.resend_api_key_set && cfg.resend_from_email);
if (!emailConfigured) { return []; }

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const lastSent = staticData.lastErrorEmailSent || 0;
const WINDOW_MS = 15 * 60 * 1000;

staticData.errorCount = (staticData.errorCount || 0) + 1;
if (!staticData.firstErrorTime) staticData.firstErrorTime = now;

if (now - lastSent < WINDOW_MS) {
  return [];
}

const totalCount = staticData.errorCount;
const firstErrorTime = staticData.firstErrorTime;

const item = $('Error Trigger').first().json;
const projectName = cfg.project_name;
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const firstErrorStr = new Date(firstErrorTime).toISOString();
const errorsInWindow = totalCount > 1
  ? `${totalCount} errors since ${firstErrorStr}`
  : '1 — first in this window';

/* Older error payloads lack execution.error. */
const errObj = item.execution?.error || item.error || {};
const nodeName = item.execution?.lastNodeExecuted || item.error?.node?.name || '—';
const errMessage = errObj.message || 'Unknown error';
const executionUrl = item.execution?.url || '';

const subject = `❌ [n8n][${projectName}] ${item.workflow.name} failed`
  + (totalCount > 1 ? ` (total: ${totalCount})` : '');

const toEmail = emailConfigured ? cfg.developer_email.replace('@', `+n8n-${projectName}@`) : '';

const html = [
  '<div style="font-family:sans-serif;max-width:600px">',
  '<h2 style="color:#cc0000;margin-bottom:16px">❌ n8n Workflow Failed</h2>',
  '<table style="border-collapse:collapse;width:100%;font-size:14px">',
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 16px 8px 0;color:#666;white-space:nowrap">Workflow</td><td style="padding:8px 0"><b>${esc(item.workflow.name)}</b></td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 16px 8px 0;color:#666">Error</td><td style="padding:8px 0;color:#cc0000">${esc(errMessage)}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 16px 8px 0;color:#666">Node</td><td style="padding:8px 0">${esc(nodeName)}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 16px 8px 0;color:#666">Mode</td><td style="padding:8px 0">${item.execution?.mode ?? 'trigger failure'}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 16px 8px 0;color:#666">Errors in window</td><td style="padding:8px 0">${errorsInWindow}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 16px 8px 0;color:#666">Time</td><td style="padding:8px 0">${new Date().toISOString()}</td></tr>`,
  `<tr><td style="padding:8px 16px 8px 0;color:#666">Execution</td><td style="padding:8px 0">${executionUrl ? `<a href="${executionUrl}">View in n8n →</a>` : '—'}</td></tr>`,
  '</table></div>'
].join('');

const bodyJson = JSON.stringify({
  from: cfg.resend_from_email,
  to: toEmail,
  subject: subject,
  html: html,
});

return [{ json: { ...item, _errorCount: totalCount, _firstErrorTime: firstErrorStr, _emailConfigured: emailConfigured, _to: toEmail, _subject: subject, _bodyJson: bodyJson } }];

/* continueRegularOutput reports failed sends as { error }; keep them eligible for retry. */
if (!$input.first().json.error) {
  const staticData = $getWorkflowStaticData('global');
  staticData.lastErrorEmailSent = Date.now();
  staticData.errorCount = 0;
  staticData.firstErrorTime = null;
}
return [];
